using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF9: Default discriminator property renamed from "Discriminator" to "$type".
            // Existing 500K documents use "Discriminator", and direct SQL queries reference c.Discriminator.
            entity.HasDiscriminator<string>("Discriminator");

            // EF9: id values no longer include the discriminator (e.g. "123" instead of "Product|123").
            // Existing documents have the old compound format; without this, FindAsync/point-reads fail.
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // EF9: HasIndex now throws for Cosmos entities.
        // Cosmos indexing is managed via the container's indexing policy, not EF Core.
        // Removed: modelBuilder.Entity<Product>().HasIndex(p => p.Sku);
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

